async function searchGoogle(query) {
  await tool.navigate({ tabId: googleTab, url: "https://www.google.com/search?q=" + encodeURIComponent(query) });
  await tool.wait_for({ tabId: googleTab, condition: "load_state", value: "load", timeout_ms: 15000 });
  const links = await browserjs(googleTab, () => {
    return Array.from(document.querySelectorAll('a'))
      .filter(a => a.href && a.querySelector('h3'))
      .map(a => ({ text: a.querySelector('h3').textContent.trim(), href: a.href }));
  });
  return links;
}

const batch = [
  "ONR Long Range BAA Machine Learning Reasoning and Intelligence",
  "ARO Broad Agency Announcement Information Sciences Intelligent Systems",
  "AFOSR Research Interests BAA Computational Cognition Machine Intelligence",
  "NIH NLM Research Grants in Biomedical Informatics and Data Science R01",
  "NEH Digital Humanities Advancement Grants"
];

for (const q of batch) {
  const results = await searchGoogle(q);
  console.log(`=== Query: ${q} ===`);
  for (const r of results.slice(0, 2)) {
    console.log(`  - ${r.text}: ${r.href}`);
  }
}

