const tabs = [787784243, 787784244, 787784245, 787784246, 787784247, 787784248, 787784249, 787784250];

for (const tabId of tabs) {
  try {
    await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  } catch (e) {}
}

const ctx = await tool.tabs_context({ _: "" });
const results = [];
for (const tabId of tabs) {
  const p = ctx.pages.find(x => x.tabId === tabId);
  let text = "";
  try {
    const res = await browser.read({ tabId, maxChars: 1500 });
    text = res.text.slice(0, 500).replace(/\n+/g, ' ');
  } catch (e) {
    text = "Error: " + e.message;
  }
  results.push({ tabId, title: p?.title, url: p?.url, snippet: text });
}
console.log(JSON.stringify(results, null, 2));

